import importlib.util, itertools
spec=importlib.util.spec_from_file_location('tower','tower-2.py'); tw=importlib.util.module_from_spec(spec); spec.loader.exec_module(tw)
L=tw.L8(); S=set(L)
# generic generator with a replaceable 2S bound
def cells(sbound):
    out=[]
    for n in range(1,4):
      for l in range(0,min(1,n-1)+1):
        for k in range(1,min(3,4*l+2)+1):
          for q in range(0,k+1):
            for e in range(1,4):
              for f in range(0,min(1,e-1)+1):
                for g in range(0,min(4*f+2,q)+1):
                  for S2 in range(0,sbound(k)+1):
                    out.append((n,l,k,q,e,f,g,S2))
    return out
assert set(cells(lambda k:k))==S
y=(1,0,1,0,1,0,0,2); print('y in Λ8:', y in S)
rev=set(cells(lambda k: 2 if k==1 else k)); new=rev-S
print('revised rule (2S≤2 at k=1): new cells', len(new), ' y among them', y in new, ' -> "74 further" + y =', len(new))
# closure of revised set under coordinatewise min/max
def closed(X):
    Xl=list(X); Xs=set(X)
    for a in Xl:
        for b in Xl:
            if tuple(map(max,a,b)) not in Xs or tuple(map(min,a,b)) not in Xs: return False
    return True
print('revised set closed under join/meet (E=0):', closed(rev), ' size', len(rev))
forg=set(cells(lambda k:k+1)); print('forged rule 2S≤k+1: new cells vs Λ8', len(forg-S), '; vs revised set', len(forg-rev))
# per-k breakdown of forged additions
from collections import Counter
print('  forged additions by k:', Counter(c[2] for c in forg-S))
# deletion repair via tightest monotone two-variable bounds (upper f_ij non-decreasing, lower g_ij non-decreasing) + box
import numpy as np
X=np.array(L); d=8
lo=X.min(0); hi=X.max(0)
def closure(Xs):
    A=np.array(sorted(Xs))
    # tightest upper bounds: for each (i,j): f_ij(v)=max{x_j : x_i<=v}; tightest lower: g_ij(v)=min{x_j : x_i>=v}
    F={}; G={}
    for i in range(d):
        for j in range(d):
            if i==j: continue
            f={}; g={}
            for v in range(lo[i],hi[i]+1):
                m=A[A[:,i]<=v]; f[v]=m[:,j].max() if len(m) else -1
                mm=A[A[:,i]>=v]; g[v]=mm[:,j].min() if len(mm) else 10**6
            F[(i,j)]=f; G[(i,j)]=g
    out=set()
    for z in itertools.product(*[range(lo[i],hi[i]+1) for i in range(d)]):
        ok=True
        for (i,j),f in F.items():
            if z[j]>f[z[i]] or z[j]<G[(i,j)][z[i]]: ok=False; break
        if ok: out.add(z)
    return out
C=closure(S); print('closure(Λ8) == Λ8:', C==S, len(C))
fails=[]
for idx,x in enumerate(L):
    Xs=S-{x}
    if x not in closure(Xs): fails.append(x)
print('deletion repair over ALL 976 cells: failures', len(fails), fails[:5])
EOF

